## 7️⃣ Cart & Checkout

### 7.1 Cart State (Redux Slice)

```ts
// src/store/slices/cartSlice.ts
import { createSlice, PayloadAction } from '@reduxjs/toolkit';

interface CartItem {
  productId: string;
  quantity: number;
}

interface CartState {
  items: CartItem[];
}

const initialState: CartState = { items: [] };

export const cartSlice = createSlice({
  name: 'cart',
  initialState,
  reducers: {
    addItem: (state, action: PayloadAction<CartItem>) => {
      const existing = state.items.find((i) => i.productId === action.payload.productId);
      if (existing) existing.quantity += action.payload.quantity;
      else state.items.push(action.payload);
    },
    removeItem: (state, action: PayloadAction<string>) => {
      state.items = state.items.filter((i) => i.productId !== action.payload);
    },
    clearCart: (state) => {
      state.items = [];
    },
  },
});

export const { addItem, removeItem, clearCart } = cartSlice.actions;
export default cartSlice.reducer;
```

### 7.2 Checkout Flow (Stripe)

```tsx
// src/pages/checkout.tsx
import { useSelector } from 'react-redux';
import { RootState } from '../store/store';
import { loadStripe } from '@stripe/stripe-js';
import { useEffect } from 'react';

const stripePromise = loadStripe(process.env.NEXT_PUBLIC_STRIPE_PUBLISHABLE_KEY!);

export default function Checkout() {
  const cart = useSelector((state: RootState) => state.cart.items);

  const handleCheckout = async () => {
    const stripe = await stripePromise;
    const res = await fetch('/api/create-checkout-session', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: JSON.stringify({ items: cart }),
    });
    const session = await res.json();
    await stripe.redirectToCheckout({ sessionId: session.id });
  };

  return (
    <div className="container mx-auto p-4">
      <h1 className="text-3xl font-bold mb-4">Checkout</h1>
      {/* Render cart summary */}
      <button onClick={handleCheckout} className="btn-primary">
        Pay with Stripe
      </button>
    </div>
  );
}
```

> **API Route** (`/api/create-checkout-session`) will call Stripe’s SDK to create a session and return the session ID.

---

## 8️⃣ Admin Panel (Next.js + React)

- Use `next-auth` for authentication (email/password or OAuth).
- Protect routes with `getServerSideProps` or `middleware`.
- CRUD operations via API routes that talk to your database (PostgreSQL, MongoDB, etc.).
- Use a component library (e.g., `@mui/material`) for tables, forms, and modals.

---

## 9️⃣ Testing

### 9.1 Unit Test (Jest + RTL)

```tsx
// __tests__/components/ui/Button.test.tsx
import { render, screen, fireEvent } from '@testing-library/react';
import { Button } from '../../src/components/ui/Button';

test('renders button and handles click', () => {
  const handleClick = jest.fn();
  render(<Button onClick={handleClick}>Click Me</Button>);
  const btn = screen.getByRole('button', { name: /click me/i });
  fireEvent.click(btn);
  expect(handleClick).toHaveBeenCalledTimes(1);
});
```

### 9.2 End‑to‑End (Cypress)

```js
